// Map from dropdown scenario to robot speed and accel distance
const scenarioParams: Record<string, { robotSpeed: number, accelDist: number }> = {
  CPFA: { robotSpeed: 8, accelDist: 1.5 },
  CPNA: { robotSpeed: 5, accelDist: 1 },
  CPNCO: { robotSpeed: 5, accelDist: 1 },
  CPLA: { robotSpeed: 5, accelDist: 1 },
  "CPTAfs/CPTAno": { robotSpeed: 5, accelDist: 1 },
  "CPTAfo/CPTAns": { robotSpeed: 5, accelDist: 1 },
  "CPRA/CPRC": { robotSpeed: 5, accelDist: 1.5 },
  CBFA: {robotSpeed: 20, accelDist: 6.2 },
  CBNA: {robotSpeed: 15, accelDist: 3.5 },
  "CBNA Obstructed": {robotSpeed: 10, accelDist: 2 },
  "CBLA AEB": {robotSpeed: 15, accelDist: 3.5 },
  "CBLA FCW": {robotSpeed: 20, accelDist: 6.2 },
  CBTA: {robotSpeed: 15, accelDist: 3.5 },
  CBDA: {robotSpeed: 15, accelDist: 3.5},
}

interface Props {
  networking: Networking
}

export default function Component({ networking }: Props) {
  const classes = useStyles()

  const uploadPathRef: React.MutableRefObject<any> = useRef()
  const uploadVehiclePathRef: React.MutableRefObject<any> = useRef()
  const uploadScriptRef: React.MutableRefObject<any> = useRef()
  const inputsInitialized = useRef(false)

  const [wrongExtensionSnackbarOpen, setWrongExtensionSnackbarOpen] = useState(false)
  const [script_params, setInputs] = useState({
    dropdownValue: "", overlapValue: "",
    robot_intersection_lat: "", robot_intersection_long: "",
    vehicle_intersection_lat: "", vehicle_intersection_long: "",
    vehicle_speed: "", vehicle_trackwidth: "",
  })
  const [infoOpen, setInfoOpen] = useState(false)

  const [infoOpenScript, setInfoOpenScript] = useState(false)
  const [scriptContent, setScriptContent] = useState("")

  useEffect(() => { // Match local and robot scriptContent
    if (networking.robotState.pathFollower) {
      setScriptContent(networking.robotState.pathFollower.scriptContent || "")
    }
  }, [networking.robotState.pathFollower, networking.robotState.pathFollower?.scriptContent])

  useEffect(() => { // Match local and robot script_params and show them in the input boxes on first startup
    const params = networking.robotState.pathFollower?.params
    if (params && Object.keys(params).length > 0 && !inputsInitialized.current) {
      setInputs({
        dropdownValue: params.dropdownValue || "",
        overlapValue: params.overlapValue || "",
        robot_intersection_lat: params.robot_intersection_lat || "",
        robot_intersection_long: params.robot_intersection_long || "",
        vehicle_intersection_lat: params.vehicle_intersection_lat || "",
        vehicle_intersection_long: params.vehicle_intersection_long || "",
        vehicle_speed: params.vehicle_speed || "",
        vehicle_trackwidth: params.vehicle_trackwidth || "",
      })
      inputsInitialized.current = true
    }
  }, [networking.robotState.pathFollower?.params])

  const [inputErrors, setInputErrors] = useState({
    robot_intersection_lat: "",
    robot_intersection_long: "",
    vehicle_intersection_lat: "",
    vehicle_intersection_long: "",
    vehicle_speed: "",
    vehicle_trackwidth: "",
    script_select: "",
    percent_overlap: ""
  })

  function uploadPath() {
    const file = uploadPathRef.current.files[0]
    uploadPathRef.current.value = "" // This is needed for uploading file with same filename but different content

    if (file.name.split(".")[1] !== "txt") {
      setWrongExtensionSnackbarOpen(true)
      return
    }

    const reader = new FileReader()
    reader.addEventListener("load", (event: any) => {
      const fileContent = event.target.result
      networking.senders.uploadPath(file.name, fileContent)
    })
    reader.readAsText(file)
  }

  function uploadVehiclePath() {
    const file = uploadVehiclePathRef.current.files[0]
    uploadVehiclePathRef.current.value = "" // This is needed for uploading file with same filename but different content

    if (file.name.split(".")[1] !== "txt") {
      setWrongExtensionSnackbarOpen(true)
      return
    }

    const reader = new FileReader()
    reader.addEventListener("load", (event: any) => {
      const fileContent = event.target.result
      networking.senders.uploadVehiclePath(file.name, fileContent)
    })
    reader.readAsText(file)
  }

  function uploadScript() {
    const file = uploadScriptRef.current.files[0]
    uploadScriptRef.current.value = "" // This is needed for uploading file with same filename but different content

    if (!file) return
  
    if (file.name.split(".")[1] !== "py") {
      setWrongExtensionSnackbarOpen(true)
      uploadScriptRef.current.value = ""
      return
    }

    const reader = new FileReader()
    reader.addEventListener("load", (event: any) => {
      const fileContent = event.target.result
      setScriptContent(fileContent)
      networking.senders.uploadScript(file.name, fileContent)
      storeScriptParams(fileContent)
      uploadScriptRef.current.value = ""
    })
    reader.readAsText(file, "UTF-8")
  }

  // Generate Python script from user inputs
  function submitScriptParameters() {
    let newErrors = { ...inputErrors }
    let hasError = false
  
    Object.keys(script_params).forEach((key) => {
      if (key === "dropdownValue" || key === "overlapValue") return //Skip dropdown values (non numbers)
      const inputValue = script_params[key as keyof typeof script_params].trim()
      const numericValue = Number(inputValue) // Convert input to number
    
      if (inputValue === "" || isNaN(numericValue) || numericValue === 0) { //Throw error for blanks, zeros, or no numeric values for all inputs
        newErrors[key as keyof typeof inputErrors] = "Input must be a non-zero number"
        hasError = true
      } else if (key === "vehicle_trackwidth" && numericValue <= 0) { //Vehicle trackwidth must be positive
        newErrors[key as keyof typeof inputErrors] = "Value must be positive"
        hasError = true
      } else {
        newErrors[key as keyof typeof inputErrors] = "" //Clear previous errors
      }
    })

    if (!script_params.dropdownValue) { //Throw error if not script selected in dropdown menu
      newErrors.script_select = "Choose a script"
      hasError = true
    } else {
      newErrors.script_select = "" //Clear error
    }
  
    if (!script_params.overlapValue) { //Throw error if no overlap percent selected in dropdown menu
      newErrors.percent_overlap = "Choose an overlap value"
      hasError = true
    } else if (script_params.dropdownValue !== "CPNA" && script_params.overlapValue !== "50") {
      newErrors.percent_overlap = "25 and 75% overlap only used for CPNA"
      hasError = true
    } else {
      newErrors.percent_overlap = "" // Clear error
    }

    setInputErrors(newErrors)
    if (hasError) return // Stop if errors exist

    const {
      vehicle_intersection_lat,
      vehicle_intersection_long,
      vehicle_speed,
    } = script_params

    const { overlapLat: riLatShifted, overlapLong: riLongShifted } = overlap_intersection() // Check overlap value to adjust intersection pos
    const viLat = vehicle_intersection_lat || 0
    const viLong = vehicle_intersection_long || 0
    const vSpeed = vehicle_speed || 0
    const { robotSpeed, accelDist } = scenarioParams[script_params.dropdownValue]
    const accel = ((robotSpeed/3.6) ** 2 / (2*accelDist)/9.81)

    // Lat/long vals to 7 decimals for script
    const riLatStr = riLatShifted.toFixed(7)
    const riLongStr = riLongShifted.toFixed(7)
    const viLatStr = Number(viLat).toFixed(7)
    const viLongStr = Number(viLong).toFixed(7)

    const pythonScript = `
rc = RobotCommander()

## Inputs: Stride intersection latitude, Stride intersection longitude, vehicle intersection latitude, 
## vehicle intersection longitude, Stride speed(kph), Stride accel(g), Stride accel dist(m), vehicle speed(kph)
rc.custom_compensation(${riLatStr}, ${riLongStr}, ${viLatStr}, ${viLongStr}, ${robotSpeed}, ${accel}, ${accelDist}, ${vSpeed})
      `
    setScriptContent(pythonScript)

    if (networking.robotState.pathFollower) { // Match robot state scriptContent with generated script
      networking.robotState.pathFollower.scriptContent = pythonScript
    }

    const generatedScriptName = "Euro_NCAP_script.py"
    networking.senders.uploadScript(generatedScriptName, pythonScript)

    if (networking.robotState.pathFollower) {
      networking.robotState.pathFollower.scriptName = generatedScriptName
      networking.robotState.pathFollower.scriptContent = pythonScript
    }
    storeScriptParams(pythonScript)
  }

  function overlap_intersection() {
    const overlapNumber = Number(script_params.overlapValue)
    const trackwidth = Number(script_params.vehicle_trackwidth)
    const shiftDiff = 0.25 * trackwidth
    const robot_intersection_lat = Number(script_params.robot_intersection_lat)
    const robot_intersection_long = Number(script_params.robot_intersection_long)
    const EN = EN_factors(Number(script_params.robot_intersection_lat))
    const E_factor = EN[0]
    const N_factor = EN[1]
    let newLat, newLong
  
    if (overlapNumber === 25) { // Find 25% overlap pos
      const direction_to_shift = (networking.robotState.gps.heading + Math.PI) // Shift behind
      const northShift = shiftDiff * Math.cos(direction_to_shift);
      const eastShift = shiftDiff * Math.sin(direction_to_shift);
      [newLat, newLong] = NE2LL(northShift, eastShift, robot_intersection_lat, robot_intersection_long, E_factor, N_factor)
    } else if (overlapNumber === 75) { // Find 75% overlap pos
      const direction_to_shift = (networking.robotState.gps.heading) // Shift ahead
      const northShift = shiftDiff * Math.cos(direction_to_shift);
      const eastShift = shiftDiff * Math.sin(direction_to_shift);
      [newLat, newLong] = NE2LL(northShift, eastShift, robot_intersection_lat, robot_intersection_long, E_factor, N_factor)
    } else { // Keep 50% overlap
      newLat = robot_intersection_lat
      newLong = robot_intersection_long
    }
    return { overlapLat: newLat, overlapLong: newLong }
  }

  function getRobotIntersection() {
    setInputs({
      ...script_params,
      robot_intersection_lat: networking.robotState.gps.latitude.toFixed(7),
      robot_intersection_long: networking.robotState.gps.longitude.toFixed(7)
    })
  }

  function getVehicleIntersection() {
    setInputs({
      ...script_params,
      vehicle_intersection_lat: networking.robotState.targetVehicle.latitude.toFixed(7),
      vehicle_intersection_long: networking.robotState.targetVehicle.longitude.toFixed(7)
    })
  }

  function clearScriptParams() {
    setInputs({ 
      dropdownValue: "",
      overlapValue: "",
      robot_intersection_lat: "", 
      robot_intersection_long: "",
      vehicle_intersection_lat: "", 
      vehicle_intersection_long: "", 
      vehicle_speed: "", 
      vehicle_trackwidth: "" 
    })
  }

  function downloadTestScript() {
    if (!scriptContent || !networking.robotState.pathFollower.scriptName) return
    const blob = new Blob([scriptContent], { type: "text/plain;charset=utf-8" })
    const url = URL.createObjectURL(blob)
    const a = document.createElement("a")
    a.href = url
    a.download = networking.robotState.pathFollower.scriptName
    a.click()
    URL.revokeObjectURL(url)
  }

  function storeScriptParams(currentScriptContent:string) {
    networking.senders.uploadScriptParams({
      params: script_params,
      scriptContent: currentScriptContent,
    })
  }  

  return (
    <div>
      <Typography variant="body1" className={classes.notes}>
        Note that the robot only stores the most recently uploaded path and script files.
      </Typography>

      <Typography variant="body1" className={classes.body}>
        Path (.txt file): {networking.robotState.pathFollower.pathName} <br />
        Vehicle Path (.txt file): {networking.robotState.pathFollower.vehiclePathName} <br />
        Script (.py file): {networking.robotState.pathFollower.scriptName}
        {networking.robotState.pathFollower.scriptName && (
          <IconButton size="small" onClick={() => setInfoOpenScript(true)}>
            <InfoIcon color="primary" fontSize="small" />
          </IconButton>
        )}
      </Typography>

      <Button className={classes.button} variant="outlined" color="primary" component="label">
        upload path
        <input
          type="file"
          ref={uploadPathRef}
          onChange={() => {
            uploadPath()
          }}
          hidden
        />
      </Button>

      <Button className={classes.button} variant="outlined" color="primary" component="label">
        upload vehicle path
        <input
          type="file"
          ref={uploadVehiclePathRef}
          onChange={() => {
            uploadVehiclePath()
          }}
          hidden
        />
      </Button>

      <Button className={classes.button} variant="outlined" color="primary" component="label">
        upload script
        <input
          type="file"
          ref={uploadScriptRef}
          onChange={() => {
            uploadScript()
          }}
          hidden
        />
      </Button>

  {/* Box around dropdown, user inputs, and script submit button */}
  <div
    className={classes.formGrid}
    style={{
      border: "1px solid #ccc",
      borderRadius: 8,
      padding: 16,
      marginTop: 24,
      width: "fit-content",
      position: "relative",
      background: "#fff",
    }}
  >
<Typography
  variant="subtitle1"
  style={{
    position: "absolute",
    top: -12,
    left: 16,
    transform: "none",
    background: "#fff",
    padding: "0 6px",
    color: "#3f51b5",
    fontWeight: 600,
  }}
>
  Euro NCAP Parameters
</Typography>
    {/* Dropdown + info icon */}
    <div className={classes.dropdownRow} style={{ marginBottom: -8 }}>{/* -8 margin to remove extra gap between dropdowns due to info icon*/}
      <FormControl 
        className={classes.dropdownMenu} 
        style={{ flex: 1 }} // Keep same width as input boxes
        error={!!inputErrors.script_select} >
        <InputLabel shrink style={{ fontSize: 16, color: "#3f51b5", marginBottom: 4 }}>
          Preset Scripts
        </InputLabel>
        <Select
          value={script_params.dropdownValue}
          onChange={(e) => {
            setInputs({ ...script_params, dropdownValue: e.target.value as string })
            setInputErrors({ ...inputErrors, script_select: "" }) // clear error on select
          }}
          displayEmpty
          renderValue={(selected: unknown) => selected === "" ? <em>Select Script</em> : selected as string}
        >
          <MenuItem value="CPFA">CPFA</MenuItem>
          <MenuItem value="CPNA">CPNA</MenuItem>
          <MenuItem value="CPNCO">CPNCO</MenuItem>
          <MenuItem value="CPLA">CPLA</MenuItem>
          <MenuItem value="CPTAfs/CPTAno">CPTAfs/CPTAno</MenuItem>
          <MenuItem value="CPTAfo/CPTAns">CPTAfo/CPTAns</MenuItem>
          <MenuItem value="CPRA/CPRC">CPRA/CPRC</MenuItem>
          <MenuItem value="CBFA">CBFA</MenuItem>
          <MenuItem value="CBNA">CBNA</MenuItem>
          <MenuItem value="CBNA Obstructed">CBNA Obstructed</MenuItem>
          <MenuItem value="CBLA AEB">CBLA AEB</MenuItem>
          <MenuItem value="CBLA FCW">CBLA FCW</MenuItem>
          <MenuItem value="CBTA">CBTA</MenuItem>
          <MenuItem value="CBDA">CBDA</MenuItem>
        </Select>
        <FormHelperText>{inputErrors.script_select}</FormHelperText>
      </FormControl>
      <IconButton onClick={() => setInfoOpen(true)}>
        <InfoIcon color="primary" />
      </IconButton>
    </div>

    {/* Info button dialog box */}
    <Dialog open={infoOpen} onClose={() => setInfoOpen(false)}>
      <DialogTitle style={{ paddingBottom: 0 }}>Script Information</DialogTitle>
      <DialogContent style={{ paddingTop: 8 }}> 
        <Typography style={{ fontSize: "1rem", lineHeight: 1.4, whiteSpace: "pre-line"}}>
          {script_params.dropdownValue ? scriptInfo[script_params.dropdownValue] : "Select a script for details"}
        </Typography>
      </DialogContent>
    </Dialog>

    <Dialog open={infoOpenScript} onClose={() => setInfoOpenScript(false)} maxWidth="md" fullWidth>
  <DialogTitle style={{ paddingBottom: 0 }}>
    Uploaded Script Contents
  </DialogTitle>
  <DialogContent 
    style={{ 
      paddingTop: 8, 
      maxHeight: "70vh",
      overflow: "auto" 
    }}
  >
    <Typography
      component="pre"
      style={{
        fontSize: "0.875rem",
        whiteSpace: "pre-wrap",
        wordBreak: "break-word",
        fontFamily: "monospace",
      }}
    >
      {scriptContent || "No script content available"}
    </Typography>
  </DialogContent>
</Dialog>

    {/* Overlap dropdown */}
    <FormControl
      className={classes.dropdownMenu}
      style={{ flex: 1 }}
      error={!!inputErrors.percent_overlap}
    >
      <InputLabel shrink style={{ fontSize: 16, color: "#3f51b5", marginBottom: 4 }}>
        % Overlap
      </InputLabel>
      <Select
        value={script_params.overlapValue}
        onChange={(e) => {
          setInputs({ ...script_params, overlapValue: e.target.value as string })
          setInputErrors({ ...inputErrors, percent_overlap: "" }) // clear error
        }}
        displayEmpty
        renderValue={(selected: unknown) => selected === "" ? <em>Select Overlap</em> : selected as string}
      >
        <MenuItem value="25">25</MenuItem>
        <MenuItem value="50">50</MenuItem>
        <MenuItem value="75">75</MenuItem>
      </Select>
      <FormHelperText>{inputErrors.percent_overlap}</FormHelperText>
    </FormControl>

    {/* User Input Boxes */}
    <TextField
      className={classes.fullWidthInput}
      label="Robot Intersection Latitude"
      variant="outlined"
      size="small"
      value={script_params.robot_intersection_lat}
      onChange={(e) => setInputs({ ...script_params, robot_intersection_lat: e.target.value })}
      error={!!inputErrors.robot_intersection_lat}
      helperText={inputErrors.robot_intersection_lat}
    />
    <TextField
      className={classes.fullWidthInput}
      label="Robot Intersection Longitude"
      variant="outlined"
      size="small"
      value={script_params.robot_intersection_long}
      onChange={(e) => setInputs({ ...script_params, robot_intersection_long: e.target.value })}
      error={!!inputErrors.robot_intersection_long}
      helperText={inputErrors.robot_intersection_long}
    />
    <TextField
      className={classes.fullWidthInput}
      label="Vehicle Intersection Latitude"
      variant="outlined"
      size="small"
      value={script_params.vehicle_intersection_lat}
      onChange={(e) => setInputs({ ...script_params, vehicle_intersection_lat: e.target.value })}
      error={!!inputErrors.vehicle_intersection_lat}
      helperText={inputErrors.vehicle_intersection_lat}
    />
    <TextField
      className={classes.fullWidthInput}
      label="Vehicle Intersection Longitude"
      variant="outlined"
      size="small"
      value={script_params.vehicle_intersection_long}
      onChange={(e) => setInputs({ ...script_params, vehicle_intersection_long: e.target.value })}
      error={!!inputErrors.vehicle_intersection_long}
      helperText={inputErrors.vehicle_intersection_long}
    />
    <TextField
      className={classes.fullWidthInput}
      label="Vehicle Speed (kph)"
      variant="outlined"
      size="small"
      value={script_params.vehicle_speed}
      onChange={(e) => setInputs({ ...script_params, vehicle_speed: e.target.value })}
      error={!!inputErrors.vehicle_speed}
      helperText={inputErrors.vehicle_speed}
    />
    <TextField
      className={classes.fullWidthInput}
      label="Vehicle Trackwidth (m)"
      variant="outlined"
      size="small"
      value={script_params.vehicle_trackwidth}
      onChange={(e) => setInputs({ ...script_params, vehicle_trackwidth: e.target.value })}
      error={!!inputErrors.vehicle_trackwidth}
      helperText={inputErrors.vehicle_trackwidth}
    />

    <Button
      variant="outlined"
      color="primary"
      style={{
        height: 40,
        borderRadius: 4,
        fontSize: "0.875rem",
        fontWeight: 400,
        textTransform: "none",
      }}
      onClick={getRobotIntersection}
    >
      Get Robot Intersection
    </Button>

    <Button
      variant="outlined"
      color="primary"
      style={{
        height: 40,
        borderRadius: 4,
        fontSize: "0.875rem",
        fontWeight: 400,
        textTransform: "none",
      }}
      onClick={getVehicleIntersection}
    >
      Get Vehicle Intersection
    </Button>

    <div className={classes.gridSpanAll}>
      <Button
        variant="outlined"
        color="primary"
        fullWidth
        style={{
          height: 40,
          borderRadius: 4,
          fontSize: "0.875rem",
          fontWeight: 400,
          textTransform: "none",
        }}
        onClick={submitScriptParameters}
      >
        Submit Script Parameters
      </Button>
    </div>

    <Button
        variant="outlined"
        color="primary"
        style={{
          height: 40,
          borderRadius: 4,
          fontSize: "0.875rem",
          fontWeight: 400,
          textTransform: "none",
        }}
        onClick={downloadTestScript}
      >
        Download Test Script
      </Button>

    <Button
        variant="outlined"
        color="primary"
        style={{
          height: 40,
          borderRadius: 4,
          fontSize: "0.875rem",
          fontWeight: 400,
          textTransform: "none",
        }}
        onClick={clearScriptParams}
      >
        Clear Script Parameters
      </Button>
  </div>
  
      <Snackbar
        className={classes.snackbar}
        open={wrongExtensionSnackbarOpen}
        autoHideDuration={6000}
        onClose={() => {
          setWrongExtensionSnackbarOpen(false)
        }}
        anchorOrigin={{ vertical: "top", horizontal: "center" }}
      >
        <MuiAlert elevation={6} variant="filled" severity="warning">
          Incorrect file extension
        </MuiAlert>
      </Snackbar>
    </div>
  )
}
